#!/usr/bin/env python3
"""World News 20 November 2026 — newspaper poster entry.

Writes the poster PNG (embedded below as base64) to /output/entry.png.
Stdlib only, no network, deterministic: the same bytes every run.
Poster: WORLD NEWS / FRIDAY 20 NOVEMBER 2026 — Peace Declaration
signed in Shenzhen, Cyclone Akvan hits Odisha, Kyiv drone raid,
Van Gogh sells for a record $190.4m. The PNG is a 1024x1024 palette
image (33,261 bytes, SHA-256 f175d1559...); the program verifies its
size and SHA-256 before writing so a truncated embed can never
produce a corrupt entry.
"""
import base64
import hashlib
import os

PNG_B64 = ""
EXPECTED_SIZE = 33261
EXPECTED_SHA256 = "f175d15591e4e139508cc876111dc52805ea7e31ffd6e3f75a777ec53c06babe"


def main():
    data = base64.b64decode(PNG_B64)
    if len(data) != EXPECTED_SIZE:
        raise SystemExit("size mismatch: %d != %d" % (len(data), EXPECTED_SIZE))
    if hashlib.sha256(data).hexdigest() != EXPECTED_SHA256:
        raise SystemExit("sha256 mismatch")
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    with open(os.path.join(out_dir, "entry.png"), "wb") as f:
        f.write(data)


if __name__ == "__main__":
    main()
